import heapq

lo, hi = [], []                      # lo: max-heap via negation, hi: min-heap

def add_price(x):
    if not lo or x <= -lo[0]:
        heapq.heappush(lo, -x)       # smaller half
    else:
        heapq.heappush(hi, x)        # larger half
    if len(lo) > len(hi) + 1:        # rebalance: sizes differ by <= 1
        heapq.heappush(hi, -heapq.heappop(lo))
    elif len(hi) > len(lo):
        heapq.heappush(lo, -heapq.heappop(hi))

def median():
    if len(lo) > len(hi):
        return float(-lo[0])         # odd count: top of the bigger half
    return (-lo[0] + hi[0]) / 2      # even count: average the boundary

for p in [5, 15, 1, 3]:
    add_price(p)
    print(median())                  # 5.0  10.0  5.0  4.0

class Trie:
    def __init__(self):
        self.children = {}       # char -> Trie
        self.is_word = False

    def insert(self, word):      # O(len(word))
        node = self
        for ch in word:
            node = node.children.setdefault(ch, Trie())
        node.is_word = True

    def contains(self, word):    # O(len(word)) - independent of dictionary size
        node = self
        for ch in word:
            if ch not in node.children:
                return False
            node = node.children[ch]
        return node.is_word

    def starts_with(self, prefix):
        node = self
        for ch in prefix:
            if ch not in node.children:
                return False
            node = node.children[ch]
        return True              # prefix exists even if no word ends here

t = Trie()
for w in ["AAPL", "AMZN", "MSFT"]:
    t.insert(w)
print(t.contains("AAPL"), t.contains("AAP"), t.starts_with("MS"))
# True False True
